from typing import List

class Solution:
    def findDiagonalOrder(self, mat: List[List[int]]) -> List[int]:
        m, n = len(mat), len(mat[0])
        ans = []
        for s in range(m + n - 1):
            diag = []
            for r in range(m):
                for c in range(n):
                    if r + c == s:
                        diag.append(mat[r][c])
            if s % 2 == 0:
                diag.reverse()
            ans.extend(diag)
        return ans

